@startuml

class Person {
  + HealthNumber : string
  + FirstName : string
  + LastName : string
  + Address : string
  + PhoneNumber : string
}

class Doctor extends Person {
  + PractitionerNumber : int
  + Signature : string
}

class Patient extends Person {
  + DateOfBirth : date
}

class Requisition {
  + ValidFrom : date
  + RepetitionCount : int
  + RepetitionInterval : string
}

class Test {
  + Name : string
}

class TestType {
  + Name : string
  + Duration : string
}

class TestResult {
  + Result : boolean
  + Report : string
}

class Lab {
  + Address : string
  + BusinessHours : string
  + RegistrationNumber : string
  + Fee : float
}

class Appointment {
  + ConfirmationNumber : string
  + StartTime : time
  + EndTime : time
}

class AppointmentConfirmation {
  + ConfirmationNumber : string
  + Date : date
  + StartTime : time
  + EndTime : time
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : receives
Requisition "1" *-- "*" Test : contains
Test "*" -- "1" TestType : is of type
Doctor "1" -- "*" TestResult : views
Patient "1" -- "*" TestResult : views
Patient "1" -- "*" Appointment : makes
Requisition "1" -- "0..1" Appointment : for
Lab "1" -- "*" Appointment : hosts
Lab "1" -- "*" Appointment : location

@enduml

